-- Rezané fólie: kompletná ponuka (Siser cez ideo.sk) — nové skupiny fólií a všetky farby s fotkami vzoriek (public/folie).
-- Ceny €/bm pri NOVÝCH skupinách sú ODHAD podľa podobných materiálov — skontroluj ich v PrintStudio → Rezané fólie. Bezpečné spustiť opakovane.
alter table folie_farby add column if not exists foto_url text;
