insert into folie_farby (kod, druh_kod, nazov, hex, foto_url, poradie)
select e->>0, d.f, e->>1, e->>2, case when (e->>3)::int = 1 then 'https://printstudio-pro.vercel.app/folie/' || (e->>0) || '.webp' end, t.ord
from d, jsonb_array_elements(d.a) with ordinality as t(e, ord)
on conflict (kod) do update set foto_url = excluded.foto_url, poradie = excluded.poradie;
